--region import

---@type Engine.Lib.KTool
local KTool                    = CS.Engine.Lib.KTool
---@type MaidCoffeeUtils
local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
--endregion

--region define
local CatHouseCaptureTextureComplete = Constants.EventNames.CatHouseCaptureTextureComplete
--endregion


--- from: Assets/BundleResources/Prefabs/OverseaManage/OverseaManageCatballLevelupSuccess.prefab
---@class OverseaManageCatBallLevelUpSuccess
---@field Env                           	OverseaManageCatBallLevelUpSuccess      
---@field controller                    	Engine.UI.UILuaDialog                   
---@field TextNumberAfterEnergy         	TMPro.TextMeshProUGUI                   
---@field TextNumberBeforeEnergy        	TMPro.TextMeshProUGUI                   
---@field TextNumberAfterLv             	TMPro.TextMeshProUGUI                   
---@field TextNumberBeforeLv            	TMPro.TextMeshProUGUI                   
---@field TextName                      	UnityEngine.UI.Text                     
---@field ImgCatballIcon                	UnityEngine.UI.RawImage                 
local OverseaManageCatBallLevelUpSuccess = Class('OverseaManageCatBallLevelUpSuccess')

function OverseaManageCatBallLevelUpSuccess:__init()

end

function OverseaManageCatBallLevelUpSuccess:__delete()
    self.controller = nil
end


function OverseaManageCatBallLevelUpSuccess:Awake()
    KTool.SetActive(self.ImgCatballIcon.gameObject, false)

end

function OverseaManageCatBallLevelUpSuccess:OnDestroy()
    if self.__EventCaptureTextureCompleteAction then
        Events.RemoveListener(CatHouseCaptureTextureComplete, self.__EventCaptureTextureCompleteAction)
        self.__EventCaptureTextureCompleteAction = nil
    end
    
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

--region init

function OverseaManageCatBallLevelUpSuccess:InitData(params)
    local parameters   = params
    local playerCatId  = parameters.playerCatId
    local oldLevel     = parameters.oldLevel

    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    ---@type CatEggDojo
    local catEggDojo   = eggComponent:GetCat(playerCatId)
    ---@type MaidCoffeeCatRollConfigVo
    local vo           = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(catEggDojo.catId)
        
    self._oldLevel = oldLevel
    self._newLevel = checkNumber(catEggDojo.level)
    self._configVo = vo
end

--endregion


--region logic

function OverseaManageCatBallLevelUpSuccess:RefreshUI(params)
    self:InitData(params)
    self:RegEvent()
    self:FreshUI()
end

function OverseaManageCatBallLevelUpSuccess:RegEvent()
    if self.__EventCaptureTextureCompleteAction then
        return
    end
    self.__EventCaptureTextureCompleteAction = Events.AddListener(CatHouseCaptureTextureComplete, Bind(self, self.OnEventCaptureTextureCompleteAction))
end

function OverseaManageCatBallLevelUpSuccess:FreshUI()
    
    ---刷新等级
    self.TextNumberBeforeLv.text = self._oldLevel
    self.TextNumberAfterLv.text  = self._newLevel

    ---刷新能量
    ---@type MaidCoffeeCatRollConfigVo
    local configVo                   = self._configVo
    local initEnergy                 = configVo.energy
    self.TextNumberBeforeEnergy.text = initEnergy + MaidCoffeeUtils.CalcCatRollAdditionEnergy(self._oldLevel)
    self.TextNumberAfterEnergy.text  = initEnergy + MaidCoffeeUtils.CalcCatRollAdditionEnergy(self._newLevel)
    
    self.TextName.text               = configVo.name

    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local fileNameId = eggComponent:GetFileNameId(MaidCoffeeConstants.BornType.Adult, configVo.catId, configVo.kind1)
    self._fileNameId = fileNameId
    eggComponent:CaptureTexture(MaidCoffeeConstants.BornType.Adult, checkNumber(configVo.catId), configVo.kind1,false, fileNameId)
end


--endregion


--region get/set

--endregion


--region handler

function OverseaManageCatBallLevelUpSuccess:OnEventCaptureTextureCompleteAction(id, path)
    if self._fileNameId ~= id then return end
    self.path = path
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local texture = eggComponent:LoadCaptureTexture(path, false)
    self.ImgCatballIcon.texture = texture
    KTool.SetActive(self.ImgCatballIcon.gameObject, true)
end
--endregion


return OverseaManageCatBallLevelUpSuccess
 